    private final CustomerRepository repository;
    CustomerService(CustomerRepository r) { this.repository = r; }

    public Customer create(String name, String email) {
        var c = new Customer();
        c.setName(name);
        c.setEmail(email);
        return repository.save(c);            // INSERT (id was null)
    }

    public Optional<Customer> get(Long id) {
        return repository.findById(id);       // SELECT by PK -> Optional
    }

    public long total() {
        return repository.count();            // SELECT COUNT(*)
    }

    public void remove(Long id) {
        repository.deleteById(id);            // DELETE
    }
}
